fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    assert!(len > 0 && n > 0 && n < len);

    let mut new_list = Vec::with_capacity(len);
    let (left, right) = list.split_at(n);
    new_list.extend_from_slice(right);
    new_list.extend_from_slice(left);

    new_list
}